  // delay() oʻrniga millis() — dastur boshqa ishni ham bajara olsin
  if (millis() - oxirgi < ORALIQ) return;
  oxirgi = millis();

  float h = dht.readHumidity();       // namlik, %
  float t = dht.readTemperature();    // harorat, C

  // MAJBURIY tekshiruv: sensor javob bermasa nan qaytadi
  if (isnan(h) || isnan(t)) {
    Serial.println("XATO: sensordan javob yoʻq. Simlarni va 10 kOm rezistorni tekshiring.");
    return;
