  Serial.println("oldinga");
  chap(200); ong(190); delay(2000);        // oʻng motor kuchliroq -> 190

  Serial.println("orqaga");
  chap(-200); ong(-190); delay(2000);

  Serial.println("joyida oʻngga burilish");
  chap(180); ong(-180); delay(700);        // gʻildiraklar qarama-qarshi

  Serial.println("toʻxtash");
  toxta(); delay(1500);
}

